COMMENT ON POLICY "b03_authenticated_incidentcommunication_insert" ON public."IncidentCommunication" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
CREATE POLICY "b03_authenticated_incidentcommunication_update" ON public."IncidentCommunication" AS PERMISSIVE FOR UPDATE TO "mscqr_rls_cert_auth_owner" USING (app_rls.b03_authenticated_context_valid() AND current_setting('app.b03_operation',true)='incident-email-complete' AND "incidentId"=current_setting('app.b03_incident_id',true)) WITH CHECK (app_rls.b03_authenticated_context_valid() AND current_setting('app.b03_operation',true)='incident-email-complete' AND "incidentId"=current_setting('app.b03_incident_id',true));
COMMENT ON POLICY "b03_authenticated_incidentcommunication_update" ON public."IncidentCommunication" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
CREATE POLICY "b03_authenticated_incidentevent_insert" ON public."IncidentEvent" AS PERMISSIVE FOR INSERT TO "mscqr_rls_cert_auth_owner" WITH CHECK (app_rls.b03_authenticated_context_valid() AND current_setting('app.b03_operation',true)='incident-email-complete' AND "incidentId"=current_setting('app.b03_incident_id',true) AND "actorUserId"=current_setting('app.b03_actor_id',true));
COMMENT ON POLICY "b03_authenticated_incidentevent_insert" ON public."IncidentEvent" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
CREATE POLICY "b03_authenticated_auditlog_insert" ON public."AuditLog" AS PERMISSIVE FOR INSERT TO "mscqr_rls_cert_auth_owner" WITH CHECK (app_rls.b03_authenticated_context_valid() AND ((current_setting('app.b03_operation',true)='incident-email-complete' AND "userId"=current_setting('app.b03_actor_id',true) AND "licenseeId"=current_setting('app.b03_licensee_id',true)) OR (current_setting('app.b03_operation',true) IN ('support-ticket-update','support-ticket-message') AND "userId"=current_setting('app.b03_actor_id',true) AND "entityType"='SupportTicket' AND "entityId"=current_setting('app.b03_support_ticket_id',true))));
COMMENT ON POLICY "b03_authenticated_auditlog_insert" ON public."AuditLog" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
CREATE POLICY "b03_authenticated_actionidempotencykey_select" ON public."ActionIdempotencyKey" AS PERMISSIVE FOR SELECT TO "mscqr_rls_cert_auth_owner" USING (app_rls.b03_authenticated_context_valid() AND action='b03-incident-email');
COMMENT ON POLICY "b03_authenticated_actionidempotencykey_select" ON public."ActionIdempotencyKey" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
CREATE POLICY "b03_authenticated_actionidempotencykey_insert" ON public."ActionIdempotencyKey" AS PERMISSIVE FOR INSERT TO "mscqr_rls_cert_auth_owner" WITH CHECK (app_rls.b03_authenticated_context_valid() AND action='b03-incident-email' AND scope=current_setting('app.b03_incident_id',true));
COMMENT ON POLICY "b03_authenticated_actionidempotencykey_insert" ON public."ActionIdempotencyKey" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
CREATE POLICY "b03_authenticated_actionidempotencykey_update" ON public."ActionIdempotencyKey" AS PERMISSIVE FOR UPDATE TO "mscqr_rls_cert_auth_owner" USING (app_rls.b03_authenticated_context_valid() AND action='b03-incident-email') WITH CHECK (app_rls.b03_authenticated_context_valid() AND action='b03-incident-email');
COMMENT ON POLICY "b03_authenticated_actionidempotencykey_update" ON public."ActionIdempotencyKey" IS '{"boundary":"b03-authenticated-notification-email","ownerIdentity":"identity-auth-function-owner","scope":"live capability plus operation-specific notification or incident selector"}';
RESET ROLE;
INSERT INTO mscqr_rls_install.expected_policy(
  schema_name,table_name,policy_name,permissive,command_name,role_names,using_tree,with_check_tree,policy_comment
)
SELECT n.nspname,c.relname,p.polname,p.polpermissive,p.polcmd::text,
  ARRAY(SELECT COALESCE(role_name.rolname,'PUBLIC') FROM unnest(p.polroles) role_oid LEFT JOIN pg_roles role_name ON role_name.oid=role_oid ORDER BY COALESCE(role_name.rolname,'PUBLIC')),
  p.polqual::text,p.polwithcheck::text,obj_description(p.oid,'pg_policy')
FROM pg_policy p
JOIN pg_class c ON c.oid=p.polrelid
JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public';
UPDATE mscqr_rls_install.state SET phase='policies-installed' WHERE singleton;
COMMIT;
